import com.vaadin.flow.component.html.ListItem;
import com.vaadin.flow.component.html.Span;
import com.vaadin.flow.component.textfield.TextField;
import java.util.List;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.boot.test.context.SpringBootTest;

@SpringBootTest
class ItemsViewTest extends SpringBrowserlessTest {

    @BeforeEach
    void navigateToView() {
        navigate(ItemsView.class);
    }

    @Test
    void viewIsShownInAppLayoutWithTitle() {
        assertTrue($(AppLayout.class).exists());
        assertEquals("Item Tracker", $(H2.class).single().getText());
    }

    @Test
    void startsEmpty() {
        assertEquals("Items", $(H1.class).single().getText());
        assertEquals("Item", $(TextField.class).single().getLabel());
        assertEquals("", $(TextField.class).single().getValue());
        assertEquals("Items: 0", $(Span.class).single().getText());
        assertTrue($(ListItem.class).all().isEmpty());
    }

    @Test
    void addAppendsItemAndEmptiesField() {
        addItem("First");
        addItem("Second");

        assertEquals(List.of("First", "Second"), itemTexts());
        assertEquals("", $(TextField.class).single().getValue());
        assertEquals("Items: 2", $(Span.class).single().getText());
    }

    @Test
    void sameTextCanBeAddedMoreThanOnce() {
        addItem("Dup");
        addItem("Dup");

        assertEquals(List.of("Dup", "Dup"), itemTexts());
        assertEquals("Items: 2", $(Span.class).single().getText());
    }

    @Test
    void blankAddIsRejectedAndMarksFieldInvalid() {
        addItem("   ");
        assertTrue($(TextField.class).single().isInvalid());
        assertTrue($(ListItem.class).all().isEmpty());
        assertEquals("Items: 0", $(Span.class).single().getText());

        addItem("");
        assertTrue($(TextField.class).single().isInvalid());
        assertTrue($(ListItem.class).all().isEmpty());
        assertEquals("Items: 0", $(Span.class).single().getText());
    }

    @Test
    void validAddAfterRejectedAddClearsInvalidState() {
        addItem("");
        assertTrue($(TextField.class).single().isInvalid());

        addItem("Valid");
        assertFalse($(TextField.class).single().isInvalid());
        assertEquals(List.of("Valid"), itemTexts());
    }

    @Test
    void clearRemovesAllItemsAndItemsCanBeAddedAgain() {
        addItem("One");
        addItem("Two");

        clickButton("Clear");
        assertTrue($(ListItem.class).all().isEmpty());
        assertEquals("Items: 0", $(Span.class).single().getText());

        addItem("Three");
        assertEquals(List.of("Three"), itemTexts());
        assertEquals("Items: 1", $(Span.class).single().getText());
    }

    private void addItem(String text) {
        test($(TextField.class).single()).setValue(text);
        clickButton("Add");
    }

    private void clickButton(String text) {
        test($(Button.class).withText(text).single()).click();
    }

